def _cast_table(self, pa_table: pa.Table, json_field_paths=()) -> pa.Table:
    if self.info.features is not None:
        # adding missing columns
        for column_name in set(self.info.features) - set(pa_table.column_names):
            type = self.info.features.arrow_schema.field(column_name).type
            pa_table = pa_table.append_column(column_name, pa.array([None] * len(pa_table), type=type))
        # convert to string when needed
        for i, column_name in enumerate(pa_table.column_names):
            if pa.types.is_struct(pa_table[column_name].type) and self.info.features.get(
                column_name, None
            ) == datasets.Value("string"):
                jsonl = (
                    pa_table[column_name]
                    .to_pandas(types_mapper=pd.ArrowDtype)
                    .to_json(orient="records", lines=True)
                )
                string_array = pa.array(
                    (None if x.strip() == "null" else x.strip() for x in jsonl.split("\n") if x.strip()),
                    type=pa.string(),
                )
                pa_table = pa_table.set_column(i, column_name, string_array)
        # more expensive cast to support nested structures with keys in a different order
        # allows str <-> int/float or str to Audio for example
        pa_table = table_cast(pa_table, self.info.features.arrow_schema)
    elif json_field_paths:
        features = datasets.Features.from_arrow_schema(pa_table.schema)
        features = set_json_types_in_feature(features, json_field_paths)
        pa_table = table_cast(pa_table, features.arrow_schema)
    return pa_table

def table_cast(table: pa.Table, schema: pa.Schema):
    """Improved version of `pa.Table.cast`.

    It supports casting to feature types stored in the schema metadata.

    Args:
        table (`pyarrow.Table`):
            PyArrow table to cast.
        schema (`pyarrow.Schema`):
            Target PyArrow schema.

    Returns:
        table (`pyarrow.Table`): the casted table
    """
    if table.schema != schema:
        return cast_table_to_schema(table, schema)
    elif table.schema.metadata != schema.metadata:
        return table.replace_schema_metadata(schema.metadata)
    else:
        return table

features = Features.from_arrow_schema(schema)
table_column_names = set(table.column_names)
if not table_column_names <= set(schema.names):
    raise CastError(
        f"Couldn't cast\n{_short_str(table.schema)}\nto\n{_short_str(features)}\nbecause column names don't match",
        table_column_names=table.column_names,
        requested_column_names=list(features),
    )
arrays = [
    cast_array_to_feature(
        table[name] if name in table_column_names else pa.array([None] * len(table), type=schema.field(name).type),
        feature,
    )
    for name, feature in features.items()
]
return pa.Table.from_arrays(arrays, schema=schema)

def _wrap_for_chunked_arrays(func):
    """Apply the function on each chunk of a `pyarrow.ChunkedArray`, or on the array directly"""

    def wrapper(array, *args, **kwargs):
        if isinstance(array, pa.ChunkedArray):
            return pa.chunked_array([func(chunk, *args, **kwargs) for chunk in array.chunks])
        else:
            return func(array, *args, **kwargs)

    return wrapper

@_wrap_for_chunked_arrays
